 explain=["Primary activities take things directly from nature: farming, fishing, mining and cutting wood.","Secondary activities change raw materials into other goods: making cloth from cotton, steel from iron ore, bread from wheat in factories.","Tertiary activities are services: teaching, healthcare, transport, banking and shops. They help people and the other two kinds of work."],
 terms=["primary activity","secondary activity","tertiary activity","raw material"],
 narr=[("Primary activities take things directly from nature, like farming, fishing and mining.","primary: farming, fishing, mining"),("Secondary activities make goods from raw materials, like cloth from cotton.","secondary: factories"),("Tertiary activities are services like teaching, doctors, transport and shops.","tertiary: services"),("All three kinds of work depend on each other.","work is connected")],
 ex=("Is a tailor's work primary, secondary or tertiary?",[("A tailor turns cloth into clothes.","It changes one material into another."),("That is making goods, not taking from nature or giving a service.","It is making a product."),("So a tailor does a secondary activity.","Many tailors also sell, which is a service.")]),
